using System;

namespace Bodu.Extensions;

public partial class DateOnlyExtensionsTests
{

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.LastDateOfWeekInYear" />, when Called, returns the expected value.
    /// </summary>
    [TestMethod]
    [DynamicData(nameof(DateTimeExtensionsTests.LastDateOfWeekInYearTestData), typeof(DateTimeExtensionsTests))]
    public void LastDateOfWeekInYear_WhenCalled_ShouldReturnExpectedDate(DateTime inputDateTime, DayOfWeek dayOfWeek, DateTime expectedDateTime)
    {
        var input = DateOnly.FromDateTime(inputDateTime);
        var expected = DateOnly.FromDateTime(expectedDateTime);

        var actual = input.LastDateOfWeekInYear(dayOfWeek);

        Assert.AreEqual(expected, actual);
    }

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.LastDateOfWeekInYear" />, when DayOfWeekIsInvalid, throws <see cref="ArgumentOutOfRangeException" />.
    /// </summary>
    [TestMethod]
    public void LastDateOfWeekInYear_WhenDayOfWeekIsInvalid_ShouldThrowExactly()
    {
        var input = new DateOnly(2024, 1, 1);
        var invalidDay = (DayOfWeek)999;

        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
        {
            _ = input.LastDateOfWeekInYear(invalidDay);
        });
    }

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.LastDateOfWeekInYear" />, when UsingMaxValue, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    public void LastDateOfWeekInYear_WhenUsingMaxValue_ShouldReturnValidDate()
    {
        var input = DateOnly.MaxValue;
        var actual = input.LastDateOfWeekInYear(DayOfWeek.Friday);

        Assert.IsTrue(actual <= DateOnly.MaxValue);
    }

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.LastDateOfWeekInYear" />, when UsingMinValue, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    public void LastDateOfWeekInYear_WhenUsingMinValue_ShouldReturnInYear1()
    {
        var input = DateOnly.MinValue;
        var actual = input.LastDateOfWeekInYear(DayOfWeek.Monday);

        Assert.IsTrue(actual.Year == 1);
        Assert.IsTrue(actual <= new DateOnly(1, 12, 31));
    }

}
